import{E as fe,c as H,m as V}from"./main-7MZK2CHF.js";var v=[{id:`1`,name:`Travel`,emoji:`✈️`,description:`Airport, transportation, and trip conversations.`,slug:`travel`,level:`beginner`,items:[{id:`1-01`,topicId:`1`,term:`passport`,translation:`pasaporte`,definition:`an official document used for international travel`,examples:[`I always keep my passport in a safe pocket.`,`She forgot her passport at home yesterday.`,`They will check your passport before boarding.`],notes:`Essential for international trips.`},{id:`1-02`,topicId:`1`,term:`boarding pass`,translation:`tarjeta de embarque`,definition:`a document that allows a passenger to enter a plane`,examples:[`Please show your boarding pass at the gate.`,`He downloaded his boarding pass to his phone.`,`We had printed our boarding passes before arriving.`],notes:`Paper or digital format.`},{id:`1-03`,topicId:`1`,term:`suitcase`,translation:`maleta`,definition:`a large bag used to carry clothes and personal items while traveling`,examples:[`My suitcase is too heavy for the overhead bin.`,`She bought a new suitcase for her trip to London.`,`They were packing their suitcases all evening.`],notes:`Common travel noun.`},{id:`1-04`,topicId:`1`,term:`check-in counter`,translation:`mostrador de facturación`,definition:`the place at an airport where passengers register and drop off luggage`,examples:[`We are waiting at the check-in counter now.`,`He asked for help at the check-in counter.`,`They had already checked in online before reaching the counter.`],notes:`Used mainly at airports.`},{id:`1-05`,topicId:`1`,term:`gate`,translation:`puerta de embarque`,definition:`the area where passengers wait before entering a plane`,examples:[`Our gate is near the coffee shop.`,`She ran to the gate because the final call had started.`,`We will meet at the gate in twenty minutes.`],notes:`Often followed by a number.`},{id:`1-06`,topicId:`1`,term:`departure`,translation:`salida`,definition:`the act or time of leaving a place, especially by plane or train`,examples:[`The departure is scheduled for 8:15 a.m.`,`His departure was delayed by bad weather.`,`They are announcing departures over the speakers.`],notes:`Common in transport schedules.`},{id:`1-07`,topicId:`1`,term:`arrival`,translation:`llegada`,definition:`the act or time of reaching a destination`,examples:[`Her arrival surprised everyone at the station.`,`We checked the arrival time online.`,`They will be waiting in the arrivals hall.`],notes:`Often paired with departure.`},{id:`1-08`,topicId:`1`,term:`delay`,translation:`retraso`,definition:`a situation in which something happens later than expected`,examples:[`There is a delay because of heavy rain.`,`The train suffered a long delay last night.`,`We might face another delay during the storm.`],notes:`Used for flights, trains, buses, and trips.`},{id:`1-09`,topicId:`1`,term:`one-way ticket`,translation:`billete de ida`,definition:`a ticket for travel to a destination without a return trip`,examples:[`I need a one-way ticket to Lisbon.`,`She bought a one-way ticket for her business trip.`,`They had considered a one-way ticket before changing plans.`],notes:`Opposite of round-trip ticket.`},{id:`1-10`,topicId:`1`,term:`round-trip ticket`,translation:`billete de ida y vuelta`,definition:`a ticket that includes travel to a destination and back again`,examples:[`A round-trip ticket is cheaper this week.`,`He booked a round-trip ticket for the conference.`,`We will buy round-trip tickets tomorrow.`],notes:`Also called a return ticket.`}],tags:[`travel`,`airport`,`transportation`,`trips`]},{id:`2`,name:`Food`,emoji:`🍜`,description:`Meals, ingredients, restaurants, and ordering food.`,slug:`food`,level:`beginner`,items:[{id:`2-01`,topicId:`2`,term:`menu`,translation:`menú`,definition:`a list of food and drinks available in a restaurant`,examples:[`Could I see the menu, please?`,`She studied the menu before ordering.`,`We were looking at the dessert menu when the waiter arrived.`],notes:`Basic restaurant vocabulary.`},{id:`2-02`,topicId:`2`,term:`order`,translation:`pedir`,definition:`to ask for food or drinks in a restaurant`,examples:[`I usually order soup and salad.`,`He ordered the fish special last night.`,`They are ordering dessert now.`],notes:`Verb and noun.`},{id:`2-03`,topicId:`2`,term:`bill`,translation:`cuenta`,definition:`the statement showing how much money you must pay for a meal`,examples:[`Can we have the bill, please?`,`She paid the bill before leaving.`,`I will ask for the bill after coffee.`],notes:`In American English, “check” is also common.`},{id:`2-04`,topicId:`2`,term:`ingredients`,translation:`ingredientes`,definition:`the foods used to make a dish`,examples:[`These ingredients are fresh and local.`,`He checked the ingredients because of his allergy.`,`We had bought all the ingredients for dinner.`],notes:`Often used in cooking.`},{id:`2-05`,topicId:`2`,term:`spicy`,translation:`picante`,definition:`having a strong hot flavor from spices`,examples:[`This curry is too spicy for me.`,`She loves spicy food.`,`The sauce was spicy but delicious.`],notes:`Describes strong hot flavor.`},{id:`2-06`,topicId:`2`,term:`appetizer`,translation:`entrante`,definition:`a small dish served before the main course`,examples:[`We shared an appetizer before dinner.`,`He ordered calamari as an appetizer.`,`They are trying a new appetizer tonight.`],notes:`Also called a starter.`},{id:`2-07`,topicId:`2`,term:`main course`,translation:`plato principal`,definition:`the most important dish in a meal`,examples:[`The chicken is my favorite main course.`,`She chose pasta for her main course.`,`We had finished the main course before the music started.`],notes:`Comes after the appetizer.`},{id:`2-08`,topicId:`2`,term:`dessert`,translation:`postre`,definition:`sweet food eaten at the end of a meal`,examples:[`I rarely eat dessert after lunch.`,`He had chocolate cake for dessert.`,`They will serve dessert in a few minutes.`],notes:`Common after the main course.`},{id:`2-09`,topicId:`2`,term:`recipe`,translation:`receta`,definition:`a set of instructions for preparing a dish`,examples:[`This recipe is easy to follow.`,`My grandmother gave me her soup recipe.`,`We are trying a new recipe this weekend.`],notes:`Used in cooking contexts.`},{id:`2-10`,topicId:`2`,term:`leftovers`,translation:`sobras`,definition:`food that remains after a meal`,examples:[`We saved the leftovers for lunch.`,`She turned the leftovers into a new dish.`,`I am eating leftovers from last night.`],notes:`Always plural in common use.`}],tags:[`food`,`restaurant`,`cooking`,`meals`]},{id:`3`,name:`Work`,emoji:`💼`,description:`Office vocabulary, meetings, and professional phrases.`,slug:`work`,level:`intermediate`,items:[{id:`3-01`,topicId:`3`,term:`deadline`,translation:`fecha límite`,definition:`the latest time by which something must be finished`,examples:[`The deadline is next Friday.`,`He missed the deadline by one day.`,`We are working hard to meet the deadline.`],notes:`Very common in work and study contexts.`},{id:`3-02`,topicId:`3`,term:`meeting`,translation:`reunión`,definition:`an event in which people gather to discuss work`,examples:[`I have a meeting at ten.`,`She led the meeting yesterday.`,`They will hold another meeting tomorrow.`],notes:`Basic office vocabulary.`},{id:`3-03`,topicId:`3`,term:`coworker`,translation:`compañero de trabajo`,definition:`a person who works with you`,examples:[`My coworkers are very supportive.`,`He had lunch with a coworker.`,`She is helping her new coworker this week.`],notes:`Also written as co-worker.`},{id:`3-04`,topicId:`3`,term:`salary`,translation:`salario`,definition:`money that a person receives regularly for doing a job`,examples:[`Her salary increased this year.`,`He discussed his salary during the interview.`,`They will review salaries in December.`],notes:`Usually paid monthly in many countries.`},{id:`3-05`,topicId:`3`,term:`shift`,translation:`turno`,definition:`a period of time during which someone works`,examples:[`I start my shift at 7 a.m.`,`She worked the night shift last weekend.`,`They are changing shifts at noon.`],notes:`Common in hospitals, shops, and factories.`},{id:`3-06`,topicId:`3`,term:`task`,translation:`tarea`,definition:`a piece of work that someone must do`,examples:[`This task takes only a few minutes.`,`He completed every task on his list.`,`We will divide the tasks before the project starts.`],notes:`Often used for small units of work.`},{id:`3-07`,topicId:`3`,term:`promotion`,translation:`ascenso`,definition:`a move to a higher position or rank at work`,examples:[`She got a promotion last month.`,`He deserved that promotion.`,`They are discussing possible promotions this quarter.`],notes:`Positive career event.`},{id:`3-08`,topicId:`3`,term:`remote work`,translation:`trabajo remoto`,definition:`a way of working from home or another place outside the office`,examples:[`Remote work suits my schedule well.`,`Our team switched to remote work during the storm.`,`She will continue remote work next year.`],notes:`Also called working remotely.`},{id:`3-09`,topicId:`3`,term:`schedule`,translation:`horario`,definition:`a plan that shows when tasks or events will happen`,examples:[`My schedule is full this afternoon.`,`He changed the meeting schedule yesterday.`,`We are checking the project schedule now.`],notes:`Can be noun or verb.`},{id:`3-10`,topicId:`3`,term:`interview`,translation:`entrevista`,definition:`a formal meeting in which someone is asked questions for a job`,examples:[`Her interview went very well.`,`I prepared for the interview all weekend.`,`They will conduct interviews on Monday.`],notes:`Common in hiring contexts.`}],tags:[`work`,`office`,`career`,`meetings`]},{id:`4`,name:`Daily Life`,emoji:`🏡`,description:`Useful words and phrases for everyday routines.`,slug:`daily-life`,level:`beginner`,items:[{id:`4-01`,topicId:`4`,term:`wake up`,translation:`despertarse`,definition:`stop sleeping and become awake`,examples:[`I wake up at six every morning.`,`She woke up late on Sunday.`,`They are waking up earlier this month.`],notes:`Very common daily routine phrase.`},{id:`4-02`,topicId:`4`,term:`commute`,translation:`desplazarse al trabajo`,definition:`travel regularly between home and work or school`,examples:[`He commutes by train every day.`,`She commuted for two hours yesterday.`,`I will commute by bus next week.`],notes:`Used as verb and noun.`},{id:`4-03`,topicId:`4`,term:`do chores`,translation:`hacer las tareas del hogar`,definition:`do regular small jobs at home`,examples:[`We do chores every Saturday morning.`,`He did chores before lunch.`,`She is doing chores while listening to music.`],notes:`Examples: cleaning, washing, tidying.`},{id:`4-04`,topicId:`4`,term:`grocery shopping`,translation:`compra del supermercado`,definition:`the activity of buying food and household items`,examples:[`I do grocery shopping on Fridays.`,`They went grocery shopping after work.`,`She is making a list for grocery shopping now.`],notes:`Useful everyday expression.`},{id:`4-05`,topicId:`4`,term:`take a shower`,translation:`ducharse`,definition:`wash your body under running water`,examples:[`I take a shower before breakfast.`,`He took a shower after the gym.`,`She is taking a shower right now.`],notes:`Common daily routine phrase.`},{id:`4-06`,topicId:`4`,term:`make breakfast`,translation:`preparar el desayuno`,definition:`prepare the first meal of the day`,examples:[`She makes breakfast for the family.`,`I made breakfast early this morning.`,`We will make breakfast together tomorrow.`],notes:`Everyday home expression.`},{id:`4-07`,topicId:`4`,term:`go to bed`,translation:`irse a la cama`,definition:`go to your bed to sleep`,examples:[`The children go to bed at nine.`,`I went to bed very late last night.`,`He is going to bed earlier these days.`],notes:`Daily routine phrase.`},{id:`4-08`,topicId:`4`,term:`run errands`,translation:`hacer recados`,definition:`go out to complete small necessary tasks`,examples:[`I run errands on Saturday mornings.`,`She ran errands before visiting her parents.`,`They are running errands downtown now.`],notes:`Includes shopping, banking, and similar tasks.`},{id:`4-09`,topicId:`4`,term:`tidy up`,translation:`ordenar`,definition:`make a place neat and organized`,examples:[`Please tidy up your room.`,`He tidied up the kitchen after dinner.`,`We are tidying up before the guests arrive.`],notes:`Often used for rooms and shared spaces.`},{id:`4-10`,topicId:`4`,term:`walk the dog`,translation:`pasear al perro`,definition:`take a dog outside for exercise and a short walk`,examples:[`I walk the dog every evening.`,`She walked the dog before work.`,`They will walk the dog after dinner.`],notes:`Common pet-care phrase.`}],tags:[`daily-life`,`routines`,`home`,`habits`]},{id:`5`,name:`B1+ Phrasal verbs I`,emoji:`📘`,description:`Common phrasal verbs for B1+ learners.`,slug:`b1-phrasal-verbs-i`,level:`intermediate`,items:[{id:`5-01`,topicId:`5`,term:`back down`,translation:`ceder`,definition:`stop resisting or arguing`,examples:[`He refused to back down during the negotiation.`,`They expected her to back down, but she stayed firm.`,`I won't back down from my decision.`],notes:`Used when someone stops resisting in an argument or negotiation.`},{id:`5-02`,topicId:`5`,term:`blow up`,translation:`enfadarse mucho`,definition:`become very angry`,examples:[`She blew up when she saw the broken laptop.`,`He blew up over a minor mistake.`,`Don't blow up; let's solve it calmly.`],notes:`Informal phrasal verb for becoming suddenly very angry.`},{id:`5-03`,topicId:`5`,term:`come up with`,translation:`idear`,definition:`think of an idea or plan`,examples:[`We need to come up with a better title.`,`Can you come up with a backup plan?`,`She came up with an innovative solution.`],notes:`Common for producing ideas, plans, or solutions.`},{id:`5-04`,topicId:`5`,term:`fall for`,translation:`caer en el engaño`,definition:`believe something false`,examples:[`I almost fell for that fake message.`,`Many users fall for phishing emails.`,`Don't fall for promises that sound too good.`],notes:`Usually implies being tricked or deceived.`},{id:`5-05`,topicId:`5`,term:`get ahead`,translation:`progresar`,definition:`become successful`,examples:[`She studies hard to get ahead in her field.`,`Networking can help you get ahead at work.`,`He took extra courses to get ahead.`],notes:`Often used for career, studies, or social progress.`},{id:`5-06`,topicId:`5`,term:`get over`,translation:`superar`,definition:`recover from something`,examples:[`It took him weeks to get over the flu.`,`She is trying to get over the breakup.`,`You'll get over this setback soon.`],notes:`Can be physical recovery or emotional recovery.`},{id:`5-07`,topicId:`5`,term:`go ahead`,translation:`continuar`,definition:`start or continue`,examples:[`Go ahead and submit the form now.`,`If you're ready, go ahead and start.`,`They told us to go ahead with deployment.`],notes:`Used to give permission or signal continuation.`},{id:`5-08`,topicId:`5`,term:`hold on to`,translation:`conservar`,definition:`keep and not lose`,examples:[`Hold on to your receipt in case you need a refund.`,`Hold on to this key card.`,`He held on to hope during recovery.`],notes:`Means keep possession of something; can also be abstract (hope, beliefs).`},{id:`5-09`,topicId:`5`,term:`keep away from`,translation:`mantenerse alejado de`,definition:`avoid`,examples:[`You should keep away from unsafe websites.`,`Keep away from the edge.`,`Doctors told him to keep away from sugar.`],notes:`Used for avoiding danger, risk, or harmful situations.`},{id:`5-10`,topicId:`5`,term:`look around`,translation:`mirar alrededor`,definition:`explore a place`,examples:[`We looked around the neighborhood before renting.`,`Let's look around before we decide.`,`Tourists looked around the old town.`],notes:`Neutral expression for exploring or inspecting a place.`},{id:`5-11`,topicId:`5`,term:`look back on`,translation:`recordar con perspectiva`,definition:`remember and reflect on the past`,examples:[`I look back on that year with pride.`,`I look back on college with gratitude.`,`She looked back on her first job fondly.`],notes:`Often followed by positive or reflective memories.`},{id:`5-12`,topicId:`5`,term:`make up for`,translation:`compensar`,definition:`compensate for something`,examples:[`He made up for being late by helping extra.`,`I will make up for missed classes this weekend.`,`They made up for the delay with a discount.`],notes:`Used when compensating for a mistake, delay, or loss.`},{id:`5-13`,topicId:`5`,term:`pay off`,translation:`dar resultados`,definition:`produce good results`,examples:[`All the practice finally paid off.`,`Daily reading will pay off over time.`,`Her patience paid off in the interview.`],notes:`Describes effort producing good long-term results.`},{id:`5-14`,topicId:`5`,term:`rule out`,translation:`descartar`,definition:`eliminate as impossible`,examples:[`Doctors ruled out a serious infection.`,`Tests ruled out any serious issue.`,`We can't rule out human error yet.`],notes:`Frequent in medical, technical, and decision-making contexts.`},{id:`5-15`,topicId:`5`,term:`see through`,translation:`descubrir el engaño`,definition:`detect the truth behind a lie`,examples:[`She saw through his excuse immediately.`,`I could see through his fake smile.`,`Kids quickly see through unfair rules.`],notes:`Means recognize deception despite appearances.`},{id:`5-16`,topicId:`5`,term:`stand out`,translation:`destacar`,definition:`be easy to notice`,examples:[`Her portfolio stands out from the rest.`,`Use strong verbs to stand out in writing.`,`His bright jacket made him stand out.`],notes:`Used to highlight what is noticeably better or different.`},{id:`5-17`,topicId:`5`,term:`take over`,translation:`tomar el control`,definition:`take control of something`,examples:[`A new director will take over next month.`,`She will take over as team lead Monday.`,`Large firms often take over startups.`],notes:`Refers to assuming control, leadership, or ownership.`},{id:`5-18`,topicId:`5`,term:`turn out`,translation:`resultar`,definition:`happen in a particular way`,examples:[`The event turned out better than expected.`,`It turned out to be easier than expected.`,`How did your presentation turn out?`],notes:`Used to describe the final result of a situation.`},{id:`5-19`,topicId:`5`,term:`work on`,translation:`trabajar en`,definition:`spend time improving or developing`,examples:[`I am working on my pronunciation daily.`,`I'm working on my listening skills.`,`They worked on the project all night.`],notes:`Indicates active effort to improve or develop something.`},{id:`5-20`,topicId:`5`,term:`write off`,translation:`descartar`,definition:`dismiss as not important or useful`,examples:[`Do not write off the idea too early.`,`Don't write off small improvements.`,`The manager wrote off the expense.`],notes:`Means dismissing something as unimportant or not useful.`}],tags:[`phrasal-verbs`,`b1`,`verbs`,`intermediate`]},{id:`6`,name:`Technology`,emoji:`💻`,description:`Computers, devices, internet, and digital tools vocabulary.`,slug:`technology`,level:`beginner`,items:[{id:`6-01`,topicId:`6`,term:`AI (artificial intelligence)`,translation:`IA (inteligencia artificial)`,definition:`technology that simulates human intelligence`,examples:[`AI helps detect spam emails automatically.`,`Our team uses AI to summarize long reports.`,`Many apps now include AI-powered features.`],notes:`Usually treated as an uncountable concept in general use.`},{id:`6-02`,topicId:`6`,term:`gadget`,translation:`artilugio`,definition:`a small useful electronic device`,examples:[`My favorite gadget is my smartwatch.`,`He bought a new kitchen gadget yesterday.`,`That gadget saves me a lot of time.`],notes:`Countable noun for small practical electronic tools.`},{id:`6-03`,topicId:`6`,term:`smart device`,translation:`dispositivo inteligente`,definition:`an internet-connected electronic device`,examples:[`A smart device can be controlled from your phone.`,`This smart device tracks room temperature.`,`We connected every smart device to the same app.`],notes:`Often related to IoT devices connected to apps/cloud.`},{id:`6-04`,topicId:`6`,term:`wearable technology`,translation:`tecnología vestible`,definition:`electronics worn on the body`,examples:[`Wearable technology tracks heart rate and sleep.`,`Wearable technology is popular with runners.`,`She uses wearable technology to monitor stress.`],notes:`Common in health, sports, and fitness contexts.`},{id:`6-05`,topicId:`6`,term:`VR (headset/game)`,translation:`RV (realidad virtual)`,definition:`virtual reality equipment or experience`,examples:[`He uses a VR headset to play games.`,`The museum offers a VR tour of ancient cities.`,`I tried a VR game and felt like I was flying.`],notes:`VR stands for virtual reality; often used with headset/gaming contexts.`},{id:`6-06`,topicId:`6`,term:`freeware`,translation:`software gratuito`,definition:`software available at no cost`,examples:[`We downloaded freeware for editing images.`,`This freeware works well for basic tasks.`,`Students often use freeware to save money.`],notes:`Freeware is free of cost, but not always open-source.`},{id:`6-07`,topicId:`6`,term:`internet provider`,translation:`proveedor de internet`,definition:`a company that gives internet access`,examples:[`Our internet provider upgraded our speed.`,`Call your internet provider if the connection drops.`,`We switched internet provider for a better plan.`],notes:`Also commonly called ISP (Internet Service Provider).`},{id:`6-08`,topicId:`6`,term:`search engine`,translation:`motor de búsqueda`,definition:`a website or tool used to find information online`,examples:[`Use a search engine to find tutorials quickly.`,`This search engine gives relevant results fast.`,`I changed my default search engine yesterday.`],notes:`Used for tools that index and retrieve online information.`},{id:`6-09`,topicId:`6`,term:`web browser`,translation:`navegador web`,definition:`software used to access websites`,examples:[`Please update your web browser to the latest version.`,`My web browser crashed after opening too many tabs.`,`Use a private tab in your web browser for testing.`],notes:`Examples include Chrome, Firefox, Safari, and Edge.`},{id:`6-10`,topicId:`6`,term:`server`,translation:`servidor`,definition:`a computer that provides data or services to others`,examples:[`The server is down for maintenance tonight.`,`We deployed the app to a cloud server.`,`The server handled thousands of requests per minute.`],notes:`Server-client architecture term; server provides resources/services.`},{id:`6-11`,topicId:`6`,term:`cybersecurity`,translation:`ciberseguridad`,definition:`protection of systems and data from digital attacks`,examples:[`Cybersecurity training is required for all employees.`,`Good cybersecurity includes strong passwords.`,`The company increased cybersecurity after the incident.`],notes:`Includes prevention, detection, and response to digital threats.`},{id:`6-12`,topicId:`6`,term:`apps`,translation:`aplicaciones`,definition:`software applications for phones or computers`,examples:[`I installed new apps for language practice.`,`Too many apps can slow down your phone.`,`She organized her apps by category.`],notes:`Informal short form of “applications”.`},{id:`6-13`,topicId:`6`,term:`social network`,translation:`red social`,definition:`an online platform for connecting with people`,examples:[`She joined a social network for professionals.`,`I found old classmates on a social network.`,`That social network has strict privacy settings.`],notes:`Focuses on people/connection layer of online platforms.`},{id:`6-14`,topicId:`6`,term:`social media`,translation:`redes sociales`,definition:`websites and apps for sharing content and interaction`,examples:[`Many brands use social media for marketing.`,`He took a break from social media for a week.`,`Social media can spread news very quickly.`],notes:`Broader term for content sharing and online interaction ecosystems.`},{id:`6-15`,topicId:`6`,term:`Wi-Fi hotspot`,translation:`punto de acceso Wi‑Fi`,definition:`a place or device that provides wireless internet access`,examples:[`We used a Wi-Fi hotspot at the airport.`,`Turn on your phone as a Wi-Fi hotspot.`,`The café offers a free Wi-Fi hotspot to customers.`],notes:`Can be a physical router point or a phone sharing mobile data.`},{id:`6-16`,topicId:`6`,term:`screenshot`,translation:`captura de pantalla`,definition:`an image capture of a device screen`,examples:[`Take a screenshot and send it to support.`,`I saved a screenshot of the error message.`,`She shared a screenshot in the team chat.`],notes:`Can be noun or verb: “take a screenshot”.`}],tags:[`technology`,`internet`,`devices`,`digital`]},{id:`7`,name:`Air Travel: Verbs & Verb Phrases`,emoji:`🛫`,description:`Essential verbs and phrases used in air travel situations.`,slug:`air-travel-verbs`,level:`beginner`,items:[{id:`7-01`,topicId:`7`,term:`board`,translation:`abordar`,definition:`get onto a plane`,examples:[`Passengers will board at Gate 12.`,`We boarded the plane twenty minutes before departure.`,`Please board in groups when your zone is called.`],notes:`Use directly: “board the plane” (no preposition).`},{id:`7-02`,topicId:`7`,term:`check in`,translation:`hacer el check-in`,definition:`register for a flight and get a boarding pass`,examples:[`We checked in online the night before.`,`You should check in at least two hours early.`,`They checked in their luggage at the counter.`],notes:`Common collocation: “check in online” or “check in at the counter”.`},{id:`7-03`,topicId:`7`,term:`get on/off a plane`,translation:`subir/bajar de un avión`,definition:`enter or leave an aircraft`,examples:[`Please wait until your row is called to get off the plane.`,`Families with children can get on the plane first.`,`We got off the plane and followed the signs to baggage claim.`],notes:`Use “get on” to enter and “get off” to leave a plane.`},{id:`7-04`,topicId:`7`,term:`pick up someone`,translation:`recoger a alguien`,definition:`collect someone from the airport`,examples:[`I will pick you up at arrivals.`,`Can you pick up my cousin after her flight lands?`,`He picked me up outside Terminal 1.`],notes:`Separable phrasal verb: “pick someone up”.`},{id:`7-05`,topicId:`7`,term:`drop off someone`,translation:`dejar a alguien`,definition:`take someone to the airport and leave them there`,examples:[`She dropped off her brother at Terminal 2.`,`I will drop off my parents before work.`,`They dropped us off near the departure entrance.`],notes:`Separable phrasal verb: “drop someone off”.`},{id:`7-06`,topicId:`7`,term:`take off`,translation:`despegar`,definition:`leave the ground and begin flying`,examples:[`The flight took off on time.`,`Our plane took off just before sunset.`,`Please fasten your seatbelt before takeoff.`],notes:`In aviation, means a plane leaving the ground.`},{id:`7-07`,topicId:`7`,term:`land`,translation:`aterrizar`,definition:`arrive on the ground after flying`,examples:[`Our plane landed safely despite the rain.`,`We are expected to land at 9:30 p.m.`,`The pilot announced that we would land soon.`],notes:`Intransitive verb for arriving on the ground after flight.`},{id:`7-08`,topicId:`7`,term:`delay a flight`,translation:`retrasar un vuelo`,definition:`postpone a flight to a later time`,examples:[`Fog delayed the flight by two hours.`,`Bad weather may delay flights this evening.`,`A technical issue delayed our flight.`],notes:`Transitive usage: weather/technical issues can delay a flight.`},{id:`7-09`,topicId:`7`,term:`go through security`,translation:`pasar por seguridad`,definition:`pass airport security checks`,examples:[`You must go through security before entering the gate area.`,`We went through security in less than fifteen minutes.`,`Keep your passport ready when you go through security.`],notes:`Fixed airport phrase for security screening process.`},{id:`7-10`,topicId:`7`,term:`book a ticket`,translation:`reservar un billete`,definition:`reserve and buy a flight ticket`,examples:[`I booked a ticket to Madrid for next week.`,`She booked a ticket as soon as prices dropped.`,`Book a ticket early to get a better fare.`],notes:`Standard collocation for reserving and buying flight travel.`},{id:`7-11`,topicId:`7`,term:`take a connecting flight`,translation:`tomar un vuelo de conexión`,definition:`change planes to reach the final destination`,examples:[`We took a connecting flight in Frankfurt.`,`You may need to take a connecting flight to reach the island.`,`Our connecting flight leaves from a different terminal.`],notes:`Used when a route requires transfer through another airport.`},{id:`7-12`,topicId:`7`,term:`change flights`,translation:`cambiar de vuelo`,definition:`switch from one flight to another`,examples:[`You need to change flights in Istanbul.`,`They changed flights due to a cancellation.`,`We had only forty minutes to change flights.`],notes:`Means transferring from one flight to another during a trip.`}],tags:[`air-travel`,`airport`,`verbs`,`flights`]},{id:`8`,name:`English-Class-july- 31`,emoji:`🗣️`,description:`Phrasal verbs and useful expressions from the July 31 English class.`,slug:`english-class-july-31`,level:`intermediate`,items:[{id:`8-01`,topicId:`8`,term:`brake down`,translation:`averiarse / derrumbarse emocionalmente`,definition:`used for "break down": stop working or lose emotional control`,examples:[`My car breaks down on cold mornings.`,`She breaks down when the pressure is too high.`,`The machine breaks down if we skip maintenance.`],notes:`Kept as provided; the usual spelling is "break down".`},{id:`8-02`,topicId:`8`,term:`Put down`,translation:`menospreciar / poner`,definition:`criticize someone or place something on a surface`,examples:[`He puts people down in meetings.`,`Please put down your backpack by the door.`,`She puts down her phone before dinner.`],notes:`Meaning depends on context.`},{id:`8-03`,topicId:`8`,term:`Run down`,translation:`descuidado / agotado / resumen`,definition:`be in poor condition, feel tired, or give a short summary`,examples:[`That apartment looks run down now.`,`I feel run down after a busy week.`,`He gives me a quick run-down of the plan.`],notes:`Common as adjective and noun phrase.`},{id:`8-04`,topicId:`8`,term:`Come around`,translation:`pasar por / recuperarse / cambiar de opinión`,definition:`visit, recover, or change your opinion`,examples:[`My friends come around on Friday evenings.`,`He comes around after hearing the full story.`,`She comes around quickly after the treatment.`],notes:`Has several common uses.`},{id:`8-05`,topicId:`8`,term:`come through`,translation:`cumplir / salir adelante`,definition:`deliver what is expected or succeed in a difficult moment`,examples:[`She always comes through when the team needs help.`,`The payment comes through before noon.`,`He comes through under pressure every time.`],notes:`Often used for reliability.`},{id:`8-06`,topicId:`8`,term:`Come about`,translation:`suceder`,definition:`happen or occur`,examples:[`How does this mistake come about?`,`Big changes come about slowly.`,`The opportunity comes about through hard work.`],notes:`Common in explanations.`},{id:`8-07`,topicId:`8`,term:`Came off`,translation:`se desprendió / salió / pareció`,definition:`became detached, succeeded, or seemed in a particular way`,examples:[`The handle came off the door this morning.`,`The event came off better than we expected.`,`His comment came off as rude in the meeting.`],notes:`Past-form expression with multiple uses.`},{id:`8-08`,topicId:`8`,term:`wear and tear`,translation:`desgaste por uso`,definition:`damage caused by normal use over time`,examples:[`The contract covers normal wear and tear.`,`Daily use causes wear and tear on shoes.`,`The table shows wear and tear after many years.`],notes:`Common in rental and maintenance contexts.`},{id:`8-09`,topicId:`8`,term:`Due`,translation:`vencido / programado / debido`,definition:`expected, required, or payable at a certain time`,examples:[`The report is due tomorrow morning.`,`The rent is due on the first of the month.`,`Her train is due in ten minutes.`],notes:`Used for deadlines, schedules, and payments.`},{id:`8-10`,topicId:`8`,term:`Fine print`,translation:`letra pequeña`,definition:`important details in small text, usually in a contract or offer`,examples:[`I read the fine print before I sign anything.`,`The fine print includes extra service fees.`,`She checks the fine print on every agreement.`],notes:`Often implies hidden conditions.`},{id:`8-11`,topicId:`8`,term:`Tenance`,translation:`tenencia / arrendamiento`,definition:`used for "tenancy": the condition of renting and occupying a property`,examples:[`Their tenance starts next Monday.`,`The tenance agreement lasts one year.`,`He reviews the tenance terms before moving in.`],notes:`Kept as provided; the common form is "tenancy".`},{id:`8-12`,topicId:`8`,term:`Plead the fifth`,translation:`acogerse a la quinta enmienda`,definition:`refuse to answer a question to avoid self-incrimination`,examples:[`He pleads the fifth during the interview.`,`She pleads the fifth when the question is too personal.`,`They plead the fifth in court proceedings.`],notes:`U.S. legal expression.`}],tags:[`classroom`,`expressions`,`phrasal-verbs`,`intermediate`]},{id:`9`,name:`Clothing Phrasal Verbs`,emoji:`👕`,description:`Common phrasal verbs used for clothes, dressing, and changing outfits.`,slug:`clothing-phrasal-verbs`,level:`intermediate`,items:[{id:`9-01`,topicId:`9`,term:`try on`,translation:`probarse`,definition:`put on a piece of clothing to see if it fits or looks good`,examples:[`I try on the jacket before I buy it.`,`She tries on three dresses at the store.`,`He tries on new shoes after work.`],notes:`Common for clothes, shoes, and accessories.`},{id:`9-02`,topicId:`9`,term:`put on`,translation:`ponerse`,definition:`dress yourself in a piece of clothing`,examples:[`I put on my coat before I leave the house.`,`She puts on a hat when it is sunny.`,`He puts on clean socks every morning.`],notes:`Used for dressing yourself.`},{id:`9-03`,topicId:`9`,term:`take off`,translation:`quitarse`,definition:`remove a piece of clothing`,examples:[`I take off my shoes at the door.`,`She takes off her scarf in the office.`,`He takes off his jacket when he feels warm.`],notes:`Used for clothes, shoes, glasses, and accessories.`},{id:`9-04`,topicId:`9`,term:`dress up`,translation:`vestirse elegantemente / disfrazarse`,definition:`wear formal or special clothes`,examples:[`We dress up for weddings.`,`She dresses up for the company dinner.`,`He dresses up as a pirate for the party.`],notes:`Can mean formal clothes or a costume.`},{id:`9-05`,topicId:`9`,term:`button up`,translation:`abotonarse`,definition:`fasten clothing with buttons`,examples:[`I button up my shirt before the meeting.`,`She buttons up her coat when it is cold.`,`He buttons up his cuffs carefully.`],notes:`Often used with shirts, coats, and jackets.`},{id:`9-06`,topicId:`9`,term:`zip up`,translation:`subirse la cremallera`,definition:`close clothing with a zipper`,examples:[`I zip up my hoodie before I go outside.`,`She zips up her boots quickly.`,`He zips up his jacket in the rain.`],notes:`Used with jackets, hoodies, boots, and bags.`},{id:`9-07`,topicId:`9`,term:`roll up`,translation:`remangarse / enrollar`,definition:`fold clothing upward, especially sleeves or trouser legs`,examples:[`I roll up my sleeves before I start cooking.`,`She rolls up her jeans at the beach.`,`He rolls up his shirt sleeves in hot weather.`],notes:`Common with sleeves and trousers.`},{id:`9-08`,topicId:`9`,term:`throw on`,translation:`ponerse rápidamente`,definition:`put on clothes quickly and casually`,examples:[`I throw on a sweater before I answer the door.`,`She throws on some jeans for the trip.`,`He throws on a T-shirt and leaves.`],notes:`Informal and quick action.`},{id:`9-09`,topicId:`9`,term:`change into`,translation:`cambiarse a`,definition:`put on different clothes`,examples:[`I change into sports clothes after work.`,`She changes into pajamas at night.`,`He changes into a suit before the event.`],notes:`Used when replacing one outfit with another.`},{id:`9-10`,topicId:`9`,term:`slip on`,translation:`ponerse fácilmente`,definition:`put on clothing or shoes quickly and easily`,examples:[`I slip on my sandals before I go outside.`,`She slips on a light jacket in the evening.`,`He slips on his gloves before riding his bike.`],notes:`Common with shoes, jackets, and light clothing.`}],tags:[`clothing`,`fashion`,`phrasal-verbs`,`verbs`]},{id:`10`,name:`Phrasal Verbs with Look`,emoji:`👀`,description:`Common phrasal verbs with "look" for everyday English.`,slug:`phrasal-verbs-with-look`,level:`intermediate`,items:[{id:`10-01`,topicId:`10`,term:`look after`,translation:`cuidar de`,definition:`take care of someone or something`,examples:[`She looks after her little brother after school.`,`Can you look after my bag for a minute?`,`He looks after the office plants every week.`],notes:`Common for people, pets, and responsibilities.`},{id:`10-02`,topicId:`10`,term:`look for`,translation:`buscar`,definition:`try to find someone or something`,examples:[`I look for my keys every morning.`,`She looks for a new apartment near work.`,`They look for better solutions to the problem.`],notes:`Very common everyday phrasal verb.`},{id:`10-03`,topicId:`10`,term:`look forward to`,translation:`tener ganas de`,definition:`feel happy and excited about something in the future`,examples:[`I look forward to the weekend.`,`She looks forward to seeing her friends.`,`We look forward to your reply.`],notes:`Usually followed by a noun or gerund.`},{id:`10-04`,topicId:`10`,term:`look into`,translation:`investigar`,definition:`examine or investigate something carefully`,examples:[`The manager looks into every complaint.`,`I look into the issue before I answer.`,`They look into new ways to reduce costs.`],notes:`Common in work and problem-solving contexts.`},{id:`10-05`,topicId:`10`,term:`look out`,translation:`tener cuidado`,definition:`be careful or watch for danger`,examples:[`Look out, there is a car coming.`,`The teacher tells the children to look out when they cross the street.`,`We look out for wet floors in the hallway.`],notes:`Often used as a warning.`},{id:`10-06`,topicId:`10`,term:`look over`,translation:`revisar`,definition:`check or examine something quickly`,examples:[`I look over the report before I send it.`,`She looks over her notes before class.`,`He looks over the contract for any mistakes.`],notes:`Used for documents, work, and details.`},{id:`10-07`,topicId:`10`,term:`look through`,translation:`revisar / hojear`,definition:`read or examine something quickly`,examples:[`I look through the emails every morning.`,`She looks through the magazine while she waits.`,`They look through the files for more information.`],notes:`Similar to “look over” but often implies scanning contents.`},{id:`10-08`,topicId:`10`,term:`look up`,translation:`buscar información`,definition:`search for information in a reference source or online`,examples:[`I look up new words in the dictionary.`,`She looks up the address before she leaves.`,`They look up flight times on the website.`],notes:`Often used for dictionaries, maps, and online searches.`},{id:`10-09`,topicId:`10`,term:`look up to`,translation:`admirar`,definition:`respect and admire someone`,examples:[`Many students look up to their teachers.`,`He looks up to his older sister.`,`I look up to people who stay calm under pressure.`],notes:`Always used with a person or role model.`},{id:`10-10`,topicId:`10`,term:`look down on`,translation:`menospreciar`,definition:`think you are better than someone`,examples:[`She never looks down on people with less experience.`,`He looks down on anyone who disagrees with him.`,`They look down on that kind of work unfairly.`],notes:`Usually has a negative meaning.`}],tags:[`phrasal-verbs`,`look`,`verbs`,`everyday`]},{id:`11`,name:`Free Time Activities`,emoji:`🎉`,description:`Common words and phrases for talking about hobbies and free time activities.`,slug:`free-time-activities`,level:`beginner`,items:[{id:`11-01`,topicId:`11`,term:`stay in`,translation:`quedarse en casa`,definition:`remain at home instead of going out`,examples:[`I usually stay in on rainy evenings.`,`We stayed in last night and watched a series.`,`She is staying in this weekend to rest.`],notes:`Common for quiet plans at home.`},{id:`11-02`,topicId:`11`,term:`go out`,translation:`salir`,definition:`leave home to spend time outside, often for social activities`,examples:[`They go out most Friday nights.`,`I went out with some friends after class.`,`Are you going out tonight or staying home?`],notes:`Often used for social plans.`},{id:`11-03`,topicId:`11`,term:`eat out`,translation:`comer fuera`,definition:`eat at a restaurant instead of at home`,examples:[`We eat out once a week.`,`They ate out after the concert.`,`She is eating out with her coworkers tonight.`],notes:`Used for restaurants, cafés, or similar places.`},{id:`11-04`,topicId:`11`,term:`hang out`,translation:`pasar el rato`,definition:`spend relaxed time with other people`,examples:[`I often hang out with my cousins on Sundays.`,`We hung out at the park for hours.`,`He is hanging out with his classmates after school.`],notes:`Informal and very common in conversation.`},{id:`11-05`,topicId:`11`,term:`chill out`,translation:`relajarse`,definition:`relax and spend time without stress`,examples:[`I chill out by listening to music.`,`They chilled out at home after work.`,`She is chilling out on the sofa right now.`],notes:`Informal synonym of “relax”.`},{id:`11-06`,topicId:`11`,term:`get together`,translation:`reunirse`,definition:`meet socially with other people`,examples:[`Our family gets together every December.`,`We got together for dinner last weekend.`,`They are getting together at María’s house tonight.`],notes:`Usually refers to a planned social meeting.`},{id:`11-07`,topicId:`11`,term:`play an instrument`,translation:`tocar un instrumento`,definition:`perform music using a musical instrument`,examples:[`He plays an instrument in his free time.`,`She played the guitar at the school event.`,`I am learning to play an instrument this year.`],notes:`The image also suggests playing in a band.`},{id:`11-08`,topicId:`11`,term:`watch TV`,translation:`ver la televisión`,definition:`spend time viewing television programs`,examples:[`My parents watch TV after dinner.`,`We watched TV until midnight yesterday.`,`She is watching TV in the living room now.`],notes:`Can also extend to films and streaming content.`},{id:`11-09`,topicId:`11`,term:`take up a hobby`,translation:`empezar una afición`,definition:`start doing a new hobby or regular activity`,examples:[`Many people take up a hobby to reduce stress.`,`He took up photography last summer.`,`I am thinking of taking up chess this month.`],notes:`Often used for new long-term interests.`},{id:`11-10`,topicId:`11`,term:`work out`,translation:`hacer ejercicio`,definition:`exercise to improve fitness or health`,examples:[`I work out three times a week.`,`She worked out at the gym before work.`,`They are working out together this morning.`],notes:`Common for gym routines and exercise sessions.`},{id:`11-11`,topicId:`11`,term:`play sports`,translation:`practicar deportes`,definition:`take part in athletic games or physical activities`,examples:[`Kids play sports after school.`,`We played sports on the beach last weekend.`,`He is playing sports more often this year.`],notes:`General expression for any sport activity.`},{id:`11-12`,topicId:`11`,term:`go swimming`,translation:`ir a nadar`,definition:`go somewhere to swim as an activity`,examples:[`They go swimming every Saturday.`,`I went swimming at the lake during my vacation.`,`She is going swimming with her sister this afternoon.`],notes:`The image also includes hiking and similar activities.`},{id:`11-13`,topicId:`11`,term:`go for a walk`,translation:`ir a dar un paseo`,definition:`leave home to walk for pleasure or exercise`,examples:[`I go for a walk after lunch.`,`We went for a walk by the river yesterday.`,`He is going for a walk to clear his mind.`],notes:`Can be adapted to “go for a run” or similar activities.`},{id:`11-14`,topicId:`11`,term:`go to the cinema`,translation:`ir al cine`,definition:`visit a movie theater to watch a film`,examples:[`They go to the cinema twice a month.`,`We went to the cinema on Friday night.`,`She is going to the cinema with her friends later.`],notes:`The image also includes parties and similar places.`},{id:`11-15`,topicId:`11`,term:`have lessons`,translation:`tener clases`,definition:`attend lessons to learn a skill or subject`,examples:[`I have lessons every Tuesday evening.`,`He had guitar lessons when he was a teenager.`,`She is having dance lessons this term.`],notes:`Useful for music, language, or sports training.`},{id:`11-16`,topicId:`11`,term:`play computer games`,translation:`jugar videojuegos`,definition:`spend time playing games on a computer or console`,examples:[`My brother plays computer games after homework.`,`We played computer games all afternoon on Sunday.`,`They are playing computer games online right now.`],notes:`Common also as “play video games”.`},{id:`11-17`,topicId:`11`,term:`go online`,translation:`conectarse a internet`,definition:`connect to the internet to browse or use online services`,examples:[`I go online to check the news every morning.`,`She went online to buy concert tickets.`,`We are going online now to look for information.`],notes:`Often used with browsing, shopping, or studying.`},{id:`11-18`,topicId:`11`,term:`spend time with someone`,translation:`pasar tiempo con alguien`,definition:`be with someone for a period of time`,examples:[`I spend time with my grandparents on Sundays.`,`They spent time with their neighbors during the holiday.`,`She is spending time with her children this evening.`],notes:`Also common as “spend time doing something”.`},{id:`11-19`,topicId:`11`,term:`have fun`,translation:`divertirse`,definition:`enjoy yourself and feel happy during an activity`,examples:[`We always have fun at the beach.`,`They had fun at the festival last weekend.`,`Are you having fun at the party?`],notes:`Very common general expression.`},{id:`11-20`,topicId:`11`,term:`enjoy yourself`,translation:`disfrutar`,definition:`have a good time and feel happy in an activity or event`,examples:[`Please enjoy yourself at the party.`,`She enjoyed herself during the trip.`,`I hope you are enjoying yourself on holiday.`],notes:`Often used when talking about events or trips.`}],tags:[`free-time`,`hobbies`,`activities`,`leisure`]},{id:`12`,name:`Types of Relationships`,emoji:`💞`,description:`Vocabulary for social and romantic relationship types in everyday English.`,slug:`types-of-relationships`,level:`Beginner`,tags:[`relationships`,`social`,`everyday`],items:[{id:`13-1`,topicId:`13`,term:`acquaintance`,translation:`conocido/a`,definition:`A person you know a little, but not very well.`,examples:[`She is an acquaintance from my photography class.`,`We became acquaintances after working on one project together.`,`I had met him before, but we were only acquaintances.`],notes:`More distant than a friend.`},{id:`13-2`,topicId:`13`,term:`close friend`,translation:`amigo/a cercano/a`,definition:`A friend with whom you have a strong and trusting relationship.`,examples:[`Laura is a close friend, so I tell her everything.`,`They have been close friends since high school.`,`By next year, we will have stayed close friends for a decade.`],notes:`Implies emotional trust and frequent contact.`},{id:`13-3`,topicId:`13`,term:`best friend`,translation:`mejor amigo/a`,definition:`Your closest and most important friend.`,examples:[`My best friend always gives me honest advice.`,`He was my best friend when we were kids.`,`She has become my best friend over the years.`],notes:`Usually used for one very special friendship.`},{id:`13-4`,topicId:`13`,term:`colleague`,translation:`colega / compañero/a de trabajo`,definition:`A person you work with, especially in the same profession.`,examples:[`I discussed the proposal with a colleague this morning.`,`Her colleagues supported her during the transition.`,`We will meet our new colleagues at the orientation event.`],notes:`Professional context; more formal than coworker in some cases.`},{id:`13-5`,topicId:`13`,term:`flatmate`,translation:`compañero/a de piso`,definition:`A person who shares an apartment with you.`,examples:[`My flatmate cooks dinner every Friday.`,`I was looking for a new flatmate last month.`,`They have lived with the same flatmate for two years.`],notes:`Common in British English; US equivalent is often roommate.`},{id:`13-6`,topicId:`13`,term:`couple`,translation:`pareja`,definition:`Two people who are in a romantic relationship.`,examples:[`They are a happy couple.`,`That couple moved into our building recently.`,`By summer, they will have been a couple for five years.`],notes:`Refers to both people together.`},{id:`13-7`,topicId:`13`,term:`wife`,translation:`esposa`,definition:`A married woman in relation to her spouse.`,examples:[`His wife works as an architect.`,`She became his wife in 2020.`,`They have raised two children, and his wife has supported every step.`],notes:`Marital relationship term.`},{id:`13-8`,topicId:`13`,term:`husband`,translation:`esposo / marido`,definition:`A married man in relation to his spouse.`,examples:[`Her husband is learning Italian.`,`I met her husband at a conference last year.`,`They will celebrate their anniversary, and her husband is planning a surprise.`],notes:`Marital relationship term.`},{id:`13-9`,topicId:`13`,term:`partner`,translation:`pareja`,definition:`A person you are in a committed romantic relationship with.`,examples:[`My partner and I are moving to a new city.`,`She introduced her partner to the team.`,`They have supported each other as partners through difficult times.`],notes:`Neutral and widely used for different relationship types.`},{id:`13-10`,topicId:`13`,term:`ex`,translation:`ex / expareja`,definition:`A person you used to have a romantic relationship with.`,examples:[`I ran into my ex at the supermarket.`,`They were exes but remained respectful.`,`Over time, she has learned to talk about her ex without anger.`],notes:`Informal short form of ex-boyfriend, ex-girlfriend, or ex-partner.`},{id:`13-11`,topicId:`13`,term:`date`,translation:`cita`,definition:`A social meeting, usually romantic, between two people.`,examples:[`We are going on a date tonight.`,`Their first date went very well.`,`By next month, he will have gone on three dates with her.`],notes:`Can be a noun (the event) or verb (to date someone).`},{id:`13-12`,topicId:`13`,term:`blind date`,translation:`cita a ciegas`,definition:`A date between two people who have not met before.`,examples:[`My friend set me up on a blind date.`,`He was nervous before his blind date yesterday.`,`She has never been on a blind date, but she is open to trying it.`],notes:`Usually arranged by friends or a matchmaking service.`}]}];var T=[`beginner`,`intermediate`,`travel`,`food`,`work`,`daily-life`,`technology`,`phrasal-verbs`,`relationships`,`free-time`,`airport`,`clothing`,`classroom`,`look`,`hobbies`];var k=class i{memoryTopics=this.cloneTopics(v);getTopics(){return this.memoryTopics.map(this.withTopicDefaults)}loadTopics(){return this.getTopics()}getVocabularyItemsBySlug(e){let t=this.getTopicBySlug(e);return t?t.items:[]}getTopicById(e){let t=this.getTopics().find(o=>o.id===e)??null;return t?this.withTopicDefaults(t):null}getTopicBySlug(e){if(!e?.trim())return null;let t=this.slugify(e),o=this.getTopics().find(n=>this.slugify(n.slug??n.name)===t)??null;return o?this.withTopicDefaults(o):null}hasTopicBySlug(e){return this.getTopicBySlug(e)!==null}slugify(e){return e.toLowerCase().trim().replace(/[^a-z0-9]+/g,`-`).replace(/^-+|-+$/g,``)}hasStorage(){return typeof localStorage<`u`}cloneTopics(e){return e.map(t=>V({},t))}withTopicDefaults(e){return H(V({},e),{emoji:e.emoji??`📘`,items:e.items??[]})}static ɵfac=function(t){return new(t||i)};static ɵprov=fe({token:i,factory:i.ɵfac,providedIn:`root`})};export{k as n,T as t};